CREATE OR REPLACE FUNCTION public.admin_disburse_winner_secure(p_payout_id text, p_final_amount numeric, p_tx_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_payout record;
  v_target_address text;
  v_hash text;
  v_wallet record;
  v_old_balance numeric := 0;
  v_new_balance numeric;
  v_tx_id text;
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin role required.');
  END IF;

  SELECT * INTO v_payout FROM public.winner_payouts WHERE id = p_payout_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payout record not found.');
  END IF;

  IF v_payout.status = 'completed' THEN
    RETURN jsonb_build_object('success', true, 'already_completed', true, 'message', 'Payout was already processed.');
  END IF;

  v_target_address := v_payout.winner_address;
  v_hash := COALESCE(p_tx_hash, 'FC-' || md5(random()::text || clock_timestamp()::text));

  -- Lock wallet
  SELECT * INTO v_wallet FROM public.lottery_wallets WHERE address = v_target_address FOR UPDATE;
  IF NOT FOUND THEN
    v_old_balance := 0;
    v_new_balance := p_final_amount;
    INSERT INTO public.lottery_wallets (address, user_id, balance, lifetime_won, network, updated_at)
    VALUES (v_target_address, v_payout.user_id, v_new_balance, p_final_amount, 'FC-Virtual', now());
  ELSE
    v_old_balance := COALESCE(v_wallet.balance, 0);
    v_new_balance := round(v_old_balance + p_final_amount, 2);
    UPDATE public.lottery_wallets
    SET balance = v_new_balance,
        lifetime_won = round(COALESCE(lifetime_won, 0) + p_final_amount, 2),
        updated_at = now()
    WHERE address = v_target_address;
  END IF;

  -- Mark payout completed
  UPDATE public.winner_payouts
  SET status = 'completed',
      payout_amount = p_final_amount,
      tx_hash = v_hash,
      approved_at = now()
  WHERE id = p_payout_id;

  -- Mark ticket claimed if exists
  IF v_payout.ticket_id IS NOT NULL AND v_payout.ticket_id <> 'MANUAL' THEN
    UPDATE public.lottery_tickets
    SET claimed = true, won_amount = p_final_amount
    WHERE id = v_payout.ticket_id;
  END IF;

  -- Record in wallet_ledger
  v_tx_id := 'tx_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || substr(md5(random()::text), 1, 8);
  INSERT INTO public.wallet_ledger (
    id,
    user_id,
    wallet_address,
    transaction_type,
    amount,
    balance_before,
    balance_after,
    currency,
    reference_id,
    description,
    metadata,
    created_at
  ) VALUES (
    v_tx_id,
    v_payout.user_id,
    v_target_address,
    'lottery_win',
    p_final_amount,
    v_old_balance,
    v_new_balance,
    'Flow Coin',
    p_payout_id,
    'Lottery Winner Prize Disbursement: ' || COALESCE(v_payout.event_title, 'Pool Prize'),
    jsonb_build_object('event_id', v_payout.event_id, 'ticket_id', v_payout.ticket_id),
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'payout_id', p_payout_id,
    'credited_amount', p_final_amount,
    'new_balance', v_new_balance,
    'tx_hash', v_hash,
    'transaction_id', v_tx_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_get_rewards_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_total_claims integer := 0;
  v_total_distributed numeric := 0;
  v_active_streaks integer := 0;
  v_bonus_settings jsonb;
  v_checkin_settings jsonb;
  v_recent_claims jsonb;
BEGIN
  SELECT COUNT(*), COALESCE(SUM(amount), 0)
  INTO v_total_claims, v_total_distributed
  FROM public.wallet_ledger
  WHERE transaction_type IN ('daily_reward', 'daily_bonus');

  SELECT COUNT(*) INTO v_active_streaks
  FROM public.user_daily_streaks
  WHERE last_claimed_at >= (now() - interval '48 hours');

  SELECT value INTO v_bonus_settings FROM public.platform_settings WHERE key = 'bonus_rewards';
  SELECT value INTO v_checkin_settings FROM public.platform_settings WHERE key = 'daily_checkin';

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', id,
      'wallet_address', wallet_address,
      'amount', amount,
      'balance_after', balance_after,
      'created_at', created_at,
      'description', description
    ) ORDER BY created_at DESC
  ) INTO v_recent_claims
  FROM (
    SELECT id, wallet_address, amount, balance_after, created_at, description
    FROM public.wallet_ledger
    WHERE transaction_type IN ('daily_reward', 'daily_bonus')
    ORDER BY created_at DESC
    LIMIT 20
  ) sub;

  RETURN jsonb_build_object(
    'success', true,
    'total_claims', v_total_claims,
    'total_distributed_flo', v_total_distributed,
    'active_streaks_count', v_active_streaks,
    'bonus_settings', v_bonus_settings,
    'checkin_settings', v_checkin_settings,
    'recent_claims', COALESCE(v_recent_claims, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.buy_lottery_tickets_secure(p_event_id text, p_ticket_numbers text[], p_user_address text, p_username text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
  v_event record;
  v_wallet record;
  v_num_tickets integer;
  v_total_cost numeric;
  v_new_balance numeric;
  v_num text;
  v_now_ms bigint;
  v_ticket_id text;
  v_user_display text;
  v_tx_id text;
  v_order_ref text;
BEGIN
  v_uid := auth.uid();
  v_num_tickets := array_length(p_ticket_numbers, 1);

  IF v_num_tickets IS NULL OR v_num_tickets <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No ticket numbers provided.');
  END IF;

  -- 1. Fetch and lock event
  SELECT * INTO v_event FROM public.lottery_events WHERE id = p_event_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lottery event not found.');
  END IF;

  IF v_event.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'This lottery draw is no longer active.');
  END IF;

  IF v_event.draw_time IS NOT NULL AND v_event.draw_time <= (EXTRACT(EPOCH FROM now()) * 1000) THEN
    RETURN jsonb_build_object('success', false, 'error', 'This lottery has reached its draw cutoff time.');
  END IF;

  -- 2. Check if any ticket number is already sold
  FOREACH v_num IN ARRAY p_ticket_numbers LOOP
    IF EXISTS (
      SELECT 1 FROM public.lottery_tickets 
      WHERE event_id = p_event_id AND lpad(ticket_number, 4, '0') = lpad(v_num, 4, '0')
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Ticket #' || lpad(v_num, 4, '0') || ' is already taken. Please choose another combination.');
    END IF;
  END LOOP;

  -- 3. Calculate total cost
  v_total_cost := v_event.ticket_price * v_num_tickets;

  -- 4. Find & lock user wallet
  SELECT * INTO v_wallet FROM public.lottery_wallets 
  WHERE (v_uid IS NOT NULL AND user_id = v_uid) OR (address = p_user_address)
  ORDER BY updated_at DESC LIMIT 1
  FOR UPDATE;

  IF NOT FOUND OR COALESCE(v_wallet.balance, 0) < v_total_cost THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Insufficient Flow Coins. Required: ' || v_total_cost || ' FC, Available: ' || COALESCE(v_wallet.balance, 0) || ' FC.'
    );
  END IF;

  -- 5. Deduct wallet balance
  v_new_balance := round(v_wallet.balance - v_total_cost, 2);
  UPDATE public.lottery_wallets
  SET balance = v_new_balance, updated_at = now()
  WHERE address = v_wallet.address;

  v_now_ms := (EXTRACT(EPOCH FROM now()) * 1000)::bigint;
  v_order_ref := 'tkt-order-' || v_now_ms || '-' || floor(random() * 8999 + 1000)::text;
  v_user_display := COALESCE(p_username, '@' || substring(p_user_address from 1 for 6));

  -- 6. Insert tickets
  FOREACH v_num IN ARRAY p_ticket_numbers LOOP
    v_ticket_id := 'tkt-' || v_now_ms || '-' || floor(random() * 8999 + 1000)::text || '-' || floor(random() * 899 + 100)::text;
    INSERT INTO public.lottery_tickets (
      id,
      user_id,
      user_address,
      username,
      event_id,
      event_title,
      ticket_number,
      price,
      purchase_time,
      status,
      match_tier,
      won_amount,
      claimed,
      created_at
    ) VALUES (
      v_ticket_id,
      COALESCE(v_wallet.user_id, v_uid),
      v_wallet.address,
      v_user_display,
      p_event_id,
      v_event.title,
      lpad(v_num, 4, '0'),
      v_event.ticket_price,
      v_now_ms,
      'active',
      NULL,
      0,
      false,
      now()
    );
  END LOOP;

  -- 7. Update event stats
  UPDATE public.lottery_events
  SET pool_prize = round(pool_prize + (v_total_cost * 0.95), 2),
      tickets_sold = COALESCE(tickets_sold, 0) + v_num_tickets,
      participants_count = COALESCE(participants_count, 0) + 1
  WHERE id = p_event_id;

  -- 8. Record in wallet_ledger
  v_tx_id := 'tx_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || substr(md5(random()::text), 1, 8);
  INSERT INTO public.wallet_ledger (
    id,
    user_id,
    wallet_address,
    transaction_type,
    amount,
    balance_before,
    balance_after,
    currency,
    reference_id,
    description,
    metadata,
    created_at
  ) VALUES (
    v_tx_id,
    COALESCE(v_wallet.user_id, v_uid),
    v_wallet.address,
    'ticket_purchase',
    -v_total_cost,
    v_wallet.balance,
    v_new_balance,
    'Flow Coin',
    v_order_ref,
    'Purchased ' || v_num_tickets || ' ticket(s) for ' || v_event.title,
    jsonb_build_object('event_id', p_event_id, 'tickets_count', v_num_tickets),
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_balance', v_new_balance,
    'tickets_bought', v_num_tickets,
    'total_spent', v_total_cost,
    'transaction_id', v_tx_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_daily_bonus(p_user_address text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid UUID;
  v_addr TEXT;
  v_bonus_settings jsonb;
  v_checkin_settings jsonb;
  v_enabled boolean := true;
  v_mode text := 'streak';
  v_cooldown_hours integer := 24;
  v_cooldown_seconds integer := 86400;
  v_last_claim timestamptz;
  v_seconds_since integer;
  v_now timestamptz := now();
  v_today date := current_date;
  v_streak record;
  v_current_streak integer := 1;
  v_next_streak integer := 1;
  v_reward_amount numeric := 0.25;
  v_credit_res jsonb;
  v_day_ref text;
  v_streak_map jsonb;
  v_missed_policy text := 'reset';
  v_notif_res jsonb;
BEGIN
  v_uid := COALESCE(p_user_id, auth.uid());
  v_addr := p_user_address;

  IF v_uid IS NULL AND v_addr IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required to claim daily FLO Coin rewards.');
  END IF;

  -- 1. Read admin settings
  SELECT value INTO v_bonus_settings FROM public.platform_settings WHERE key = 'bonus_rewards';
  SELECT value INTO v_checkin_settings FROM public.platform_settings WHERE key = 'daily_checkin';

  IF v_bonus_settings IS NOT NULL THEN
    v_enabled := COALESCE((v_bonus_settings->>'enabled')::boolean, true);
    v_mode := COALESCE(v_bonus_settings->>'reward_mode', 'streak');
    v_cooldown_hours := COALESCE((v_bonus_settings->>'cooldown_hours')::integer, 24);
    v_cooldown_seconds := v_cooldown_hours * 3600;
  END IF;

  IF NOT v_enabled THEN
    RETURN jsonb_build_object('success', false, 'error', 'Daily rewards are currently paused by administrator.');
  END IF;

  IF v_checkin_settings IS NOT NULL THEN
    v_streak_map := v_checkin_settings->'streak_rewards';
    v_missed_policy := COALESCE(v_checkin_settings->>'missed_day_policy', 'reset');
  END IF;

  IF v_streak_map IS NULL THEN
    v_streak_map := jsonb_build_object(
      'day1', 0.10, 'day2', 0.15, 'day3', 0.20,
      'day4', 0.25, 'day5', 0.30, 'day6', 0.40, 'day7', 1.00
    );
  END IF;

  -- 2. Verify cooldown from wallet_ledger
  SELECT created_at INTO v_last_claim
  FROM public.wallet_ledger
  WHERE ((v_uid IS NOT NULL AND user_id = v_uid) OR (v_addr IS NOT NULL AND wallet_address = v_addr))
    AND transaction_type IN ('daily_reward', 'daily_bonus')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_last_claim IS NOT NULL THEN
    v_seconds_since := EXTRACT(EPOCH FROM (v_now - v_last_claim))::integer;
    IF v_seconds_since < v_cooldown_seconds THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Daily FLO Coin reward already claimed. Next claim available in ' || ((v_cooldown_seconds - v_seconds_since) / 3600) || 'h ' || (((v_cooldown_seconds - v_seconds_since) % 3600) / 60) || 'm.',
        'seconds_remaining', (v_cooldown_seconds - v_seconds_since)
      );
    END IF;
  END IF;

  -- 3. Calculate streak
  SELECT * INTO v_streak
  FROM public.user_daily_streaks
  WHERE (v_addr IS NOT NULL AND wallet_address = v_addr)
     OR (v_uid IS NOT NULL AND user_id = v_uid)
  LIMIT 1;

  IF v_streak IS NULL THEN
    v_current_streak := 1;
  ELSE
    IF v_streak.last_checkin_date IS NOT NULL THEN
      IF v_streak.last_checkin_date = (v_today - 1) THEN
        -- Consecutive day
        v_current_streak := (v_streak.current_streak % 7) + 1;
      ELSIF v_streak.last_checkin_date = v_today THEN
        v_current_streak := v_streak.current_streak;
      ELSE
        -- Missed day
        IF v_missed_policy = 'continue' THEN
          v_current_streak := v_streak.current_streak;
        ELSE
          v_current_streak := 1;
        END IF;
      END IF;
    ELSE
      v_current_streak := 1;
    END IF;
  END IF;

  -- 4. Calculate reward amount
  IF v_mode = 'fixed' THEN
    v_reward_amount := COALESCE((v_bonus_settings->>'fixed_amount')::numeric, 0.50);
  ELSIF v_mode = 'random' THEN
    v_reward_amount := ROUND((
      COALESCE((v_bonus_settings->>'min_amount')::numeric, 0.05) + 
      (random() * (COALESCE((v_bonus_settings->>'max_amount')::numeric, 1.00) - COALESCE((v_bonus_settings->>'min_amount')::numeric, 0.05)))
    )::numeric, 2);
  ELSE
    -- Streak mode
    v_reward_amount := COALESCE((v_streak_map->>('day' || v_current_streak))::numeric, 0.10);
  END IF;

  -- Invariant: strictly capped at <= 1.00 FLO
  IF v_reward_amount > 1.00 THEN v_reward_amount := 1.00; END IF;
  IF v_reward_amount < 0.01 THEN v_reward_amount := 0.05; END IF;

  -- 5. Reference ID for idempotency
  v_day_ref := 'daily-flo-' || to_char(v_now, 'YYYY-MM-DD') || '-' || COALESCE(v_uid::text, v_addr);

  -- 6. Atomically credit user virtual credits in wallet and ledger
  v_credit_res := public.credit_virtual_credits(
    v_reward_amount,
    'daily_reward',
    v_day_ref,
    'Daily FLO Coin Reward — Day ' || v_current_streak || ' Check-In (' || v_reward_amount || ' FLO = ' || v_reward_amount || ' USDT)',
    v_addr,
    v_uid,
    jsonb_build_object(
      'source', 'daily_flo_reward',
      'checkin_day', v_current_streak,
      'flo_amount', v_reward_amount,
      'usdt_value', v_reward_amount,
      'rate', '1 FLO = 1 USDT',
      'status', 'completed',
      'claimed_at', v_now
    )
  );

  -- 7. Update user daily streaks
  INSERT INTO public.user_daily_streaks (
    user_id,
    wallet_address,
    current_streak,
    last_checkin_date,
    last_claimed_at,
    total_checkins,
    total_flo_awarded,
    updated_at
  ) VALUES (
    v_uid,
    COALESCE(v_addr, v_uid::text),
    v_current_streak,
    v_today,
    v_now,
    1,
    v_reward_amount,
    v_now
  )
  ON CONFLICT (wallet_address) DO UPDATE SET
    current_streak = EXCLUDED.current_streak,
    last_checkin_date = EXCLUDED.last_checkin_date,
    last_claimed_at = EXCLUDED.last_claimed_at,
    total_checkins = public.user_daily_streaks.total_checkins + 1,
    total_flo_awarded = public.user_daily_streaks.total_flo_awarded + v_reward_amount,
    updated_at = v_now;

  -- 8. Create real persistent notification in user_notifications
  PERFORM public.create_user_notification(
    v_addr,
    v_uid,
    'Daily Reward Credited (Day ' || v_current_streak || ')',
    'Successfully claimed +' || v_reward_amount || ' FLO Coins (≈ $' || v_reward_amount || ' USDT). Come back tomorrow for Day ' || ((v_current_streak % 7) + 1) || '!',
    'reward',
    '/wallet'
  );

  v_next_streak := (v_current_streak % 7) + 1;

  RETURN jsonb_build_object(
    'success', true,
    'bonus_amount', v_reward_amount,
    'usdt_value', v_reward_amount,
    'new_balance', (v_credit_res->>'new_balance')::numeric,
    'current_streak', v_current_streak,
    'next_streak', v_next_streak,
    'transaction_id', (v_credit_res->>'transaction_id'),
    'message', 'Congratulations! +' || v_reward_amount || ' FLO Coins (' || v_reward_amount || ' USDT) added to your wallet.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_daily_bonus(p_user_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
  v_last_claim timestamptz;
  v_now timestamptz := now();
  v_cooldown_seconds integer := 86400; -- 24 hours
  v_seconds_since_last integer;
  v_bonus_amount numeric := 100.00;
  v_credit_res jsonb;
  v_day_ref text;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL AND p_user_address IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required to claim daily Flow Coins.');
  END IF;

  -- Check last claim
  SELECT created_at INTO v_last_claim 
  FROM public.wallet_ledger 
  WHERE ((v_uid IS NOT NULL AND user_id = v_uid) OR wallet_address = p_user_address)
    AND transaction_type = 'daily_bonus'
  ORDER BY created_at DESC 
  LIMIT 1;

  IF v_last_claim IS NOT NULL THEN
    v_seconds_since_last := EXTRACT(EPOCH FROM (v_now - v_last_claim))::integer;
    IF v_seconds_since_last < v_cooldown_seconds THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Daily bonus already claimed. Please return in ' || ((v_cooldown_seconds - v_seconds_since_last) / 3600) || ' hour(s).',
        'seconds_remaining', (v_cooldown_seconds - v_seconds_since_last)
      );
    END IF;
  END IF;

  -- Use date string as idempotency reference (e.g. daily-2026-11-06-uid)
  v_day_ref := 'daily-' || to_char(v_now, 'YYYY-MM-DD') || '-' || COALESCE(v_uid::text, p_user_address);

  -- Credit daily bonus
  v_credit_res := public.credit_virtual_credits(
    v_bonus_amount,
    'daily_bonus',
    v_day_ref,
    'Free Daily Social Grant: 100 Flow Coins',
    p_user_address,
    v_uid,
    jsonb_build_object('source', 'daily_faucet')
  );

  RETURN jsonb_build_object(
    'success', true,
    'bonus_amount', v_bonus_amount,
    'new_balance', (v_credit_res->>'new_balance')::numeric,
    'message', 'Congratulations! 100 Flow Coins added to your wallet.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_user_notifications(p_user_address text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_cleared integer := 0;
BEGIN
  UPDATE public.user_notifications
  SET is_cleared = true, cleared_at = now()
  WHERE is_cleared = false
    AND (
      (p_user_id IS NOT NULL AND user_id = p_user_id)
      OR (p_user_address IS NOT NULL AND wallet_address = p_user_address)
    );

  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'cleared_count', v_cleared);
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_virtual_credits(p_amount numeric, p_transaction_type text, p_reference_id text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_user_address text DEFAULT NULL::text, p_target_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
  v_wallet record;
  v_addr text;
  v_old_balance numeric := 0;
  v_new_balance numeric;
  v_tx_id text;
BEGIN
  v_uid := COALESCE(p_target_user_id, auth.uid());

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount must be greater than zero.');
  END IF;

  -- 1. Idempotency check: if this reference was already credited, prevent duplicate payouts
  IF p_reference_id IS NOT NULL THEN
    SELECT * INTO v_wallet FROM public.wallet_ledger 
    WHERE reference_id = p_reference_id AND transaction_type = p_transaction_type 
    LIMIT 1;
    IF FOUND THEN
      SELECT balance INTO v_new_balance FROM public.lottery_wallets WHERE (v_uid IS NOT NULL AND user_id = v_uid) OR address = p_user_address LIMIT 1;
      RETURN jsonb_build_object(
        'success', true, 
        'already_processed', true, 
        'new_balance', COALESCE(v_new_balance, 0),
        'transaction_id', v_wallet.id
      );
    END IF;
  END IF;

  -- 2. Find or create user wallet
  SELECT * INTO v_wallet FROM public.lottery_wallets 
  WHERE (v_uid IS NOT NULL AND user_id = v_uid) OR (p_user_address IS NOT NULL AND address = p_user_address)
  ORDER BY updated_at DESC LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Generate fresh wallet address if not provided
    v_addr := COALESCE(p_user_address, '0x' || substr(md5(random()::text || clock_timestamp()::text), 1, 40));
    v_old_balance := 0;
    v_new_balance := round(p_amount, 2);

    INSERT INTO public.lottery_wallets (
      address,
      user_id,
      balance,
      lifetime_won,
      network,
      updated_at
    ) VALUES (
      v_addr,
      v_uid,
      v_new_balance,
      CASE WHEN p_transaction_type IN ('lottery_win', 'game_win') THEN p_amount ELSE 0 END,
      'FC-Virtual',
      now()
    );
  ELSE
    v_addr := v_wallet.address;
    v_old_balance := COALESCE(v_wallet.balance, 0);
    v_new_balance := round(v_old_balance + p_amount, 2);

    UPDATE public.lottery_wallets
    SET balance = v_new_balance,
        lifetime_won = CASE 
          WHEN p_transaction_type IN ('lottery_win', 'game_win') 
          THEN round(COALESCE(lifetime_won, 0) + p_amount, 2)
          ELSE lifetime_won 
        END,
        user_id = COALESCE(lottery_wallets.user_id, v_uid),
        updated_at = now()
    WHERE address = v_addr;
  END IF;

  -- 3. Record in immutable ledger
  v_tx_id := 'tx_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || substr(md5(random()::text), 1, 8);
  INSERT INTO public.wallet_ledger (
    id,
    user_id,
    wallet_address,
    transaction_type,
    amount,
    balance_before,
    balance_after,
    currency,
    reference_id,
    description,
    metadata,
    created_at
  ) VALUES (
    v_tx_id,
    v_uid,
    v_addr,
    p_transaction_type,
    p_amount,
    v_old_balance,
    v_new_balance,
    'Flow Coin',
    p_reference_id,
    COALESCE(p_description, 'Credit from ' || p_transaction_type),
    p_metadata,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_balance', v_new_balance,
    'credited', p_amount,
    'transaction_id', v_tx_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.debit_virtual_credits(p_amount numeric, p_transaction_type text, p_reference_id text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_user_address text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
  v_wallet record;
  v_addr text;
  v_new_balance numeric;
  v_tx_id text;
BEGIN
  v_uid := auth.uid();
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount must be greater than zero.');
  END IF;

  -- 1. Idempotency check: if this reference was already debited, prevent double-charge
  IF p_reference_id IS NOT NULL THEN
    SELECT * INTO v_wallet FROM public.wallet_ledger 
    WHERE reference_id = p_reference_id AND transaction_type = p_transaction_type 
    LIMIT 1;
    IF FOUND THEN
      SELECT balance INTO v_new_balance FROM public.lottery_wallets WHERE (v_uid IS NOT NULL AND user_id = v_uid) OR address = p_user_address LIMIT 1;
      RETURN jsonb_build_object(
        'success', true, 
        'already_processed', true, 
        'new_balance', COALESCE(v_new_balance, 0),
        'transaction_id', v_wallet.id
      );
    END IF;
  END IF;

  -- 2. Lock user wallet with FOR UPDATE
  SELECT * INTO v_wallet FROM public.lottery_wallets 
  WHERE (v_uid IS NOT NULL AND user_id = v_uid) OR (p_user_address IS NOT NULL AND address = p_user_address)
  ORDER BY updated_at DESC LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Wallet not found.');
  END IF;

  IF COALESCE(v_wallet.balance, 0) < p_amount THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Insufficient Flow Coins. Required: ' || p_amount || ' FC, Available: ' || COALESCE(v_wallet.balance, 0) || ' FC.'
    );
  END IF;

  -- 3. Deduct balance atomically
  v_new_balance := round(v_wallet.balance - p_amount, 2);
  v_addr := v_wallet.address;

  UPDATE public.lottery_wallets
  SET balance = v_new_balance, updated_at = now()
  WHERE address = v_addr;

  -- 4. Record in immutable ledger
  v_tx_id := 'tx_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || substr(md5(random()::text), 1, 8);
  INSERT INTO public.wallet_ledger (
    id,
    user_id,
    wallet_address,
    transaction_type,
    amount,
    balance_before,
    balance_after,
    currency,
    reference_id,
    description,
    metadata,
    created_at
  ) VALUES (
    v_tx_id,
    COALESCE(v_wallet.user_id, v_uid),
    v_addr,
    p_transaction_type,
    -p_amount,
    v_wallet.balance,
    v_new_balance,
    'Flow Coin',
    p_reference_id,
    COALESCE(p_description, 'Deduction for ' || p_transaction_type),
    p_metadata,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_balance', v_new_balance,
    'deducted', p_amount,
    'transaction_id', v_tx_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_lottery_draw_secure(p_event_id text, p_custom_digits text DEFAULT NULL::text, p_custom_winner_count integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_event record;
  v_server_seed text;
  v_commit_hash text;
  v_client_seed text;
  v_combined_seed text;
  v_outcome_hash text;
  v_hex_slice text;
  v_int_val bigint;
  v_final_digits text;
  v_snapshot_count integer := 0;
  v_winner_count integer := 1;
  v_configured_winner_count integer := 1;
  v_total_collected numeric := 0;
  v_total_winner_pool numeric := 0;
  v_per_winner_amt numeric := 0;
  v_meta jsonb;
  v_audit_id text;
  v_matching_tkt_ids text[];
  v_selected_tkt_ids text[];
  v_remaining_tkt_ids text[];
  v_tkt_id text;
  v_tkt_rec record;
  v_payout_id text;
  v_ticket_accumulator text := '';
BEGIN
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin privileges required.');
  END IF;

  -- 1. Lock and check event
  SELECT * INTO v_event FROM public.lottery_events WHERE id = p_event_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lottery event not found.');
  END IF;

  IF v_event.status = 'completed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_completed', true,
      'winning_digits', v_event.winning_digits,
      'message', 'This lottery round was already finalized.'
    );
  END IF;

  -- 2. Snapshot tickets & build ticket accumulator hash
  SELECT count(*), string_agg(id, ',') INTO v_snapshot_count, v_ticket_accumulator
  FROM public.lottery_tickets 
  WHERE event_id = p_event_id AND status = 'active';

  v_snapshot_count := COALESCE(v_snapshot_count, 0);

  -- 3. Resolve seeds
  v_server_seed := COALESCE(v_event.server_seed, 'seed_' || encode(extensions.gen_random_bytes(32), 'hex'));
  v_commit_hash := COALESCE(v_event.sha256_seed, '0x' || encode(extensions.digest(v_server_seed, 'sha256'), 'hex'));
  v_client_seed := 'tickets_' || v_snapshot_count || '_' || COALESCE(substr(md5(COALESCE(v_ticket_accumulator, '')), 1, 16), 'empty');

  -- 4. Calculate Winning 4 Digits (0000 - 9999)
  IF p_custom_digits IS NOT NULL AND trim(p_custom_digits) <> '' THEN
    v_final_digits := lpad(trim(p_custom_digits), 4, '0');
    v_outcome_hash := encode(extensions.digest('custom:' || v_final_digits, 'sha256'), 'hex');
  ELSE
    -- Deterministic Provably Fair derivation: SHA256(server_seed : client_seed : event_id)
    v_combined_seed := v_server_seed || ':' || v_client_seed || ':' || p_event_id;
    v_outcome_hash := encode(extensions.digest(v_combined_seed, 'sha256'), 'hex');
    v_hex_slice := substr(v_outcome_hash, 1, 8);
    v_int_val := ('x' || v_hex_slice)::bit(32)::bigint;
    v_final_digits := lpad((v_int_val % 10000)::text, 4, '0');
  END IF;

  -- 5. Winner Count & Pool Allocation
  IF v_event.block_target IS NOT NULL AND v_event.block_target LIKE '{%' THEN
    BEGIN
      v_meta := v_event.block_target::jsonb;
    EXCEPTION WHEN OTHERS THEN
      v_meta := '{}'::jsonb;
    END;
  ELSE
    v_meta := '{}'::jsonb;
  END IF;

  v_configured_winner_count := GREATEST(1, COALESCE(p_custom_winner_count, (v_meta->>'winner_count')::integer, 1));

  -- 6. Find Winning Tickets
  -- Exact 4/4 matches first
  SELECT array_agg(id) INTO v_matching_tkt_ids
  FROM public.lottery_tickets
  WHERE event_id = p_event_id AND status = 'active' AND lpad(ticket_number, 4, '0') = v_final_digits;

  v_selected_tkt_ids := COALESCE(v_matching_tkt_ids, ARRAY[]::text[]);

  -- If fewer winners than configured and tickets exist, sample remaining lucky winners
  IF array_length(v_selected_tkt_ids, 1) IS NULL OR array_length(v_selected_tkt_ids, 1) < v_configured_winner_count THEN
    SELECT array_agg(id) INTO v_remaining_tkt_ids
    FROM (
      SELECT id FROM public.lottery_tickets
      WHERE event_id = p_event_id AND status = 'active'
        AND id <> ALL(v_selected_tkt_ids)
      ORDER BY random()
      LIMIT (v_configured_winner_count - COALESCE(array_length(v_selected_tkt_ids, 1), 0))
    ) sub;

    IF v_remaining_tkt_ids IS NOT NULL THEN
      v_selected_tkt_ids := v_selected_tkt_ids || v_remaining_tkt_ids;
    END IF;
  END IF;

  v_winner_count := GREATEST(1, COALESCE(array_length(v_selected_tkt_ids, 1), v_configured_winner_count));

  -- Calculate pool amounts
  v_total_collected := CASE 
    WHEN COALESCE(v_event.tickets_sold, 0) > 0 THEN v_event.tickets_sold * v_event.ticket_price 
    ELSE v_event.pool_prize 
  END;

  v_total_winner_pool := round((v_total_collected * COALESCE((v_meta->>'winner_share_percent')::numeric, 90)) / 100, 2);
  v_per_winner_amt := round(v_total_winner_pool / v_winner_count, 2);

  -- 7. Update Tickets & Queue Winner Payouts
  IF v_selected_tkt_ids IS NOT NULL AND array_length(v_selected_tkt_ids, 1) > 0 THEN
    -- Winning tickets
    FOREACH v_tkt_id IN ARRAY v_selected_tkt_ids LOOP
      SELECT * INTO v_tkt_rec FROM public.lottery_tickets WHERE id = v_tkt_id;

      UPDATE public.lottery_tickets
      SET status = 'won',
          match_tier = CASE WHEN lpad(v_tkt_rec.ticket_number, 4, '0') = v_final_digits THEN 'EXACT 4/4 MATCH' ELSE 'LUCKY WINNER' END,
          won_amount = v_per_winner_amt,
          claimed = false
      WHERE id = v_tkt_id;

      -- Queue into winner_payouts
      v_payout_id := 'WP-' || (EXTRACT(EPOCH FROM now()) * 1000)::bigint || '-' || substr(md5(v_tkt_id), 1, 4);
      INSERT INTO public.winner_payouts (
        id,
        event_id,
        event_title,
        ticket_id,
        user_id,
        winner_address,
        winner_username,
        winning_digits,
        tickets_sold,
        ticket_price,
        total_pool_collected,
        winner_share_percent,
        calculated_amount,
        payout_amount,
        status,
        created_at
      ) VALUES (
        v_payout_id,
        p_event_id,
        v_event.title,
        v_tkt_id,
        v_tkt_rec.user_id,
        v_tkt_rec.user_address,
        v_tkt_rec.username,
        v_final_digits,
        v_event.tickets_sold,
        v_event.ticket_price,
        v_total_collected,
        COALESCE((v_meta->>'winner_share_percent')::numeric, 90),
        v_per_winner_amt,
        v_per_winner_amt,
        'pending_approval',
        now()
      );
    END LOOP;

    -- Non-winning tickets
    UPDATE public.lottery_tickets
    SET status = 'lost',
        match_tier = 'NO MATCH',
        won_amount = 0
    WHERE event_id = p_event_id AND status = 'active' AND id <> ALL(v_selected_tkt_ids);
  ELSE
    -- No tickets sold or none active
    UPDATE public.lottery_tickets
    SET status = 'lost', match_tier = 'NO MATCH', won_amount = 0
    WHERE event_id = p_event_id AND status = 'active';
  END IF;

  -- 8. Record Draw Audit Log
  v_audit_id := 'draw_audit_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || substr(md5(random()::text), 1, 6);
  INSERT INTO public.lottery_draw_audits (
    id,
    event_id,
    event_title,
    draw_timestamp,
    winning_digits,
    commit_hash,
    revealed_seed,
    client_seed,
    outcome_hash,
    tickets_snapshot_count,
    winner_count,
    total_payout_fc,
    verified,
    metadata
  ) VALUES (
    v_audit_id,
    p_event_id,
    v_event.title,
    now(),
    v_final_digits,
    v_commit_hash,
    v_server_seed,
    v_client_seed,
    v_outcome_hash,
    v_snapshot_count,
    COALESCE(array_length(v_selected_tkt_ids, 1), 0),
    v_total_winner_pool,
    true,
    jsonb_build_object(
      'combined_seed', v_server_seed || ':' || v_client_seed || ':' || p_event_id,
      'winner_tickets', v_selected_tkt_ids
    )
  );

  -- 9. Update event status to completed & reveal seeds
  UPDATE public.lottery_events
  SET status = 'completed',
      winning_digits = v_final_digits,
      server_seed = v_server_seed,
      revealed_seed = v_server_seed,
      client_seed = v_client_seed,
      snapshot_count = v_snapshot_count,
      draw_audit_id = v_audit_id,
      draw_time = (EXTRACT(EPOCH FROM now()) * 1000)::bigint
  WHERE id = p_event_id;

  RETURN jsonb_build_object(
    'success', true,
    'event_id', p_event_id,
    'winning_digits', v_final_digits,
    'winner_count', COALESCE(array_length(v_selected_tkt_ids, 1), 0),
    'per_winner_amount', v_per_winner_amt,
    'commit_hash', v_commit_hash,
    'revealed_seed', v_server_seed,
    'audit_id', v_audit_id,
    'snapshot_count', v_snapshot_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_daily_reward_status(p_user_address text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_bonus_settings jsonb;
  v_checkin_settings jsonb;
  v_last_claim timestamptz;
  v_cooldown_hours integer := 24;
  v_cooldown_seconds integer := 86400;
  v_seconds_since integer;
  v_can_claim boolean := true;
  v_seconds_remaining integer := 0;
  v_streak record;
  v_current_streak integer := 1;
  v_next_streak integer := 1;
  v_available_reward numeric := 0.25;
  v_today date := current_date;
  v_mode text := 'streak';
  v_missed_policy text := 'reset';
  v_streak_map jsonb;
BEGIN
  -- Read admin configurations
  SELECT value INTO v_bonus_settings FROM public.platform_settings WHERE key = 'bonus_rewards';
  SELECT value INTO v_checkin_settings FROM public.platform_settings WHERE key = 'daily_checkin';

  IF v_bonus_settings IS NOT NULL THEN
    v_cooldown_hours := COALESCE((v_bonus_settings->>'cooldown_hours')::integer, 24);
    v_cooldown_seconds := v_cooldown_hours * 3600;
    v_mode := COALESCE(v_bonus_settings->>'reward_mode', 'streak');
  END IF;

  IF v_checkin_settings IS NOT NULL THEN
    v_streak_map := v_checkin_settings->'streak_rewards';
    v_missed_policy := COALESCE(v_checkin_settings->>'missed_day_policy', 'reset');
  END IF;

  -- Default streak map if empty
  IF v_streak_map IS NULL THEN
    v_streak_map := jsonb_build_object(
      'day1', 0.10, 'day2', 0.15, 'day3', 0.20,
      'day4', 0.25, 'day5', 0.30, 'day6', 0.40, 'day7', 1.00
    );
  END IF;

  -- Check existing streak for user
  SELECT * INTO v_streak
  FROM public.user_daily_streaks
  WHERE (p_user_address IS NOT NULL AND wallet_address = p_user_address)
     OR (p_user_id IS NOT NULL AND user_id = p_user_id)
  LIMIT 1;

  IF v_streak IS NOT NULL THEN
    v_current_streak := COALESCE(v_streak.current_streak, 1);
  END IF;

  -- Check last claim in wallet_ledger
  SELECT created_at INTO v_last_claim
  FROM public.wallet_ledger
  WHERE ((p_user_id IS NOT NULL AND user_id = p_user_id) OR (p_user_address IS NOT NULL AND wallet_address = p_user_address))
    AND transaction_type IN ('daily_reward', 'daily_bonus')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_last_claim IS NOT NULL THEN
    v_seconds_since := EXTRACT(EPOCH FROM (now() - v_last_claim))::integer;
    IF v_seconds_since < v_cooldown_seconds THEN
      v_can_claim := false;
      v_seconds_remaining := v_cooldown_seconds - v_seconds_since;
    END IF;
  END IF;

  -- Determine reward amount according to active mode
  IF v_mode = 'fixed' THEN
    v_available_reward := COALESCE((v_bonus_settings->>'fixed_amount')::numeric, 0.50);
  ELSIF v_mode = 'random' THEN
    v_available_reward := ROUND((COALESCE((v_bonus_settings->>'min_amount')::numeric, 0.05) + 
      ((COALESCE((v_bonus_settings->>'max_amount')::numeric, 1.00) - COALESCE((v_bonus_settings->>'min_amount')::numeric, 0.05)) * 0.4))::numeric, 2);
  ELSE
    -- Streak mode: calculate based on current streak
    v_available_reward := COALESCE((v_streak_map->>('day' || v_current_streak))::numeric, 0.10);
  END IF;

  -- Invariant: strictly capped at <= 1.00 FLO
  IF v_available_reward > 1.00 THEN v_available_reward := 1.00; END IF;
  IF v_available_reward < 0.01 THEN v_available_reward := 0.05; END IF;

  v_next_streak := (v_current_streak % 7) + 1;

  RETURN jsonb_build_object(
    'success', true,
    'can_claim', v_can_claim,
    'seconds_remaining', v_seconds_remaining,
    'available_reward', v_available_reward,
    'current_streak', v_current_streak,
    'next_streak', v_next_streak,
    'next_reward_amount', COALESCE((v_streak_map->>('day' || v_next_streak))::numeric, 0.15),
    'bonus_settings', v_bonus_settings,
    'checkin_settings', v_checkin_settings,
    'last_claimed_at', v_last_claim
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_user_game_seed(p_wallet_address text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_seed record;
  v_server_seed text;
  v_server_hash text;
  v_client_seed text;
BEGIN
  IF p_wallet_address IS NULL OR trim(p_wallet_address) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Wallet address required.');
  END IF;

  SELECT * INTO v_seed FROM public.user_game_seeds WHERE wallet_address = p_wallet_address FOR UPDATE;

  IF NOT FOUND THEN
    v_server_seed := 'seed_' || encode(extensions.gen_random_bytes(32), 'hex');
    v_server_hash := '0x' || encode(extensions.digest(v_server_seed, 'sha256'), 'hex');
    v_client_seed := 'cs_' || substr(md5(random()::text), 1, 12);

    INSERT INTO public.user_game_seeds (
      wallet_address,
      user_id,
      active_server_seed,
      active_server_hash,
      active_client_seed,
      nonce,
      updated_at
    ) VALUES (
      p_wallet_address,
      p_user_id,
      v_server_seed,
      v_server_hash,
      v_client_seed,
      0,
      now()
    ) RETURNING * INTO v_seed;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'wallet_address', v_seed.wallet_address,
    'server_hash', v_seed.active_server_hash, -- Server seed is kept secret until rotated!
    'client_seed', v_seed.active_client_seed,
    'nonce', v_seed.nonce,
    'previous_server_seed', v_seed.previous_server_seed,
    'previous_server_hash', v_seed.previous_server_hash
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_or_update_user_vip(p_wallet_address text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_uname text;
  v_game_wagered numeric := 0;
  v_game_rounds integer := 0;
  v_ticket_wagered numeric := 0;
  v_ticket_count integer := 0;
  v_total_wagered numeric := 0;
  v_total_rounds integer := 0;
  v_xp numeric := 0;
  v_tier text := 'Bronze';
  v_tier_level integer := 1;
  v_multiplier numeric := 1.0;
  v_next_tier text := 'Silver';
  v_target_xp numeric := 1000;
  v_base_xp numeric := 0;
  v_progress_pct numeric := 0;
  v_last_wheel timestamptz;
  v_last_claim timestamptz;
  v_rec record;
BEGIN
  IF p_wallet_address IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Wallet address is required');
  END IF;

  -- Get username
  SELECT username INTO v_uname FROM public.profiles 
  WHERE trc20_address = p_wallet_address OR (v_uid IS NOT NULL AND id = v_uid) 
  LIMIT 1;

  -- Aggregate Game Rounds
  SELECT 
    COALESCE(SUM(bet_amount), 0),
    COUNT(*)
  INTO v_game_wagered, v_game_rounds
  FROM public.game_rounds
  WHERE wallet_address = p_wallet_address OR (v_uid IS NOT NULL AND user_id = v_uid);

  -- Aggregate Lottery Tickets
  SELECT 
    COALESCE(COUNT(*) * 10.0, 0),
    COUNT(*)
  INTO v_ticket_wagered, v_ticket_count
  FROM public.lottery_tickets
  WHERE user_address = p_wallet_address OR (v_uid IS NOT NULL AND user_id = v_uid);

  v_total_wagered := v_game_wagered + v_ticket_wagered;
  v_total_rounds := v_game_rounds + v_ticket_count;
  v_xp := v_total_wagered * 10; -- 1 FC = 10 XP

  -- Calculate Tier & Multipliers
  IF v_xp >= 500000 THEN
    v_tier := 'Obsidian';
    v_tier_level := 6;
    v_multiplier := 3.0;
    v_next_tier := 'Max Tier';
    v_base_xp := 500000;
    v_target_xp := 500000;
    v_progress_pct := 100;
  ELSIF v_xp >= 100000 THEN
    v_tier := 'Diamond';
    v_tier_level := 5;
    v_multiplier := 2.0;
    v_next_tier := 'Obsidian';
    v_base_xp := 100000;
    v_target_xp := 500000;
    v_progress_pct := LEAST(100, ROUND(((v_xp - v_base_xp) / (v_target_xp - v_base_xp)) * 100, 1));
  ELSIF v_xp >= 20000 THEN
    v_tier := 'Platinum';
    v_tier_level := 4;
    v_multiplier := 1.5;
    v_next_tier := 'Diamond';
    v_base_xp := 20000;
    v_target_xp := 100000;
    v_progress_pct := LEAST(100, ROUND(((v_xp - v_base_xp) / (v_target_xp - v_base_xp)) * 100, 1));
  ELSIF v_xp >= 5000 THEN
    v_tier := 'Gold';
    v_tier_level := 3;
    v_multiplier := 1.25;
    v_next_tier := 'Platinum';
    v_base_xp := 5000;
    v_target_xp := 20000;
    v_progress_pct := LEAST(100, ROUND(((v_xp - v_base_xp) / (v_target_xp - v_base_xp)) * 100, 1));
  ELSIF v_xp >= 1000 THEN
    v_tier := 'Silver';
    v_tier_level := 2;
    v_multiplier := 1.1;
    v_next_tier := 'Gold';
    v_base_xp := 1000;
    v_target_xp := 5000;
    v_progress_pct := LEAST(100, ROUND(((v_xp - v_base_xp) / (v_target_xp - v_base_xp)) * 100, 1));
  ELSE
    v_tier := 'Bronze';
    v_tier_level := 1;
    v_multiplier := 1.0;
    v_next_tier := 'Silver';
    v_base_xp := 0;
    v_target_xp := 1000;
    v_progress_pct := LEAST(100, ROUND((v_xp / v_target_xp) * 100, 1));
  END IF;

  -- Upsert into user_vip_progress
  INSERT INTO public.user_vip_progress (
    wallet_address,
    user_id,
    username,
    total_wagered,
    total_rounds_played,
    xp_points,
    current_tier,
    tier_level,
    faucet_multiplier,
    updated_at
  ) VALUES (
    p_wallet_address,
    v_uid,
    COALESCE(v_uname, 'Player_' || substring(p_wallet_address from 3 for 6)),
    v_total_wagered,
    v_total_rounds,
    v_xp,
    v_tier,
    v_tier_level,
    v_multiplier,
    now()
  )
  ON CONFLICT (wallet_address) DO UPDATE SET
    user_id = COALESCE(EXCLUDED.user_id, public.user_vip_progress.user_id),
    username = COALESCE(EXCLUDED.username, public.user_vip_progress.username),
    total_wagered = EXCLUDED.total_wagered,
    total_rounds_played = EXCLUDED.total_rounds_played,
    xp_points = EXCLUDED.xp_points,
    current_tier = EXCLUDED.current_tier,
    tier_level = EXCLUDED.tier_level,
    faucet_multiplier = EXCLUDED.faucet_multiplier,
    updated_at = now()
  RETURNING last_wheel_spin_at, last_daily_claim_at INTO v_last_wheel, v_last_claim;

  RETURN jsonb_build_object(
    'success', true,
    'wallet_address', p_wallet_address,
    'username', COALESCE(v_uname, 'Player'),
    'current_tier', v_tier,
    'tier_level', v_tier_level,
    'total_wagered', v_total_wagered,
    'total_rounds', v_total_rounds,
    'xp_points', v_xp,
    'faucet_multiplier', v_multiplier,
    'next_tier', v_next_tier,
    'target_xp', v_target_xp,
    'progress_pct', v_progress_pct,
    'last_wheel_spin_at', v_last_wheel,
    'last_daily_claim_at', v_last_claim
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_user_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
    BEGIN
      -- Delete from auth.users (if still present)
      DELETE FROM auth.users WHERE id = OLD.id;

      -- Clean up any related user records across tables
      DELETE FROM public.lottery_wallets WHERE user_id = OLD.id;
      DELETE FROM public.lottery_tickets WHERE user_id = OLD.id;
      DELETE FROM public.lottery_deposits WHERE user_id = OLD.id;
      DELETE FROM public.lottery_withdrawals WHERE user_id = OLD.id;
      DELETE FROM public.support_tickets WHERE user_id = OLD.id;
      DELETE FROM public.username_changes WHERE user_id = OLD.id;
      DELETE FROM public.winner_payouts WHERE user_id = OLD.id;

      RETURN OLD;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.is_staff()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
    return exists (
        select 1 from public.profiles
        where id = auth.uid() and role = 'staff'
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.log_admin_action(p_action_type text, p_target_type text DEFAULT NULL::text, p_target_id text DEFAULT NULL::text, p_changes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_email text;
  v_role text;
  v_log_id uuid;
BEGIN
  -- Verify admin role
  SELECT email, role INTO v_email, v_role
  FROM public.profiles
  WHERE id = v_uid;

  IF v_role != 'super_admin' AND v_role != 'admin' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin role required');
  END IF;

  INSERT INTO public.admin_audit_logs (
    admin_id,
    admin_email,
    action_type,
    target_type,
    target_id,
    changes,
    created_at
  ) VALUES (
    v_uid,
    COALESCE(v_email, 'admin@earnflow.in'),
    p_action_type,
    p_target_type,
    p_target_id,
    p_changes,
    now()
  )
  RETURNING id INTO v_log_id;

  RETURN jsonb_build_object('success', true, 'log_id', v_log_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.request_withdrawal_secure(p_amount numeric, p_destination_address text, p_network text, p_user_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
    DECLARE
      v_uid uuid;
      v_wallet record;
      v_settings jsonb;
      v_min numeric := 5.0;
      v_max numeric := 10000.0;
      v_fee numeric := 1.0;
      v_net numeric;
      v_new_balance numeric;
      v_order_id text;
      v_now_ms bigint;
    BEGIN
      v_uid := auth.uid();
      IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid withdrawal amount.');
      END IF;

      -- Fetch platform limits
      SELECT value INTO v_settings FROM public.platform_settings WHERE key = 'global';
      IF v_settings IS NOT NULL THEN
        v_min := COALESCE((v_settings->>'minWithdrawal')::numeric, 5.0);
        v_max := COALESCE((v_settings->>'maxWithdrawal')::numeric, 10000.0);
      END IF;

      IF p_amount < v_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'Minimum withdrawal amount is ' || v_min || ' USDT.');
      END IF;

      IF p_amount > v_max THEN
        RETURN jsonb_build_object('success', false, 'error', 'Maximum withdrawal amount is ' || v_max || ' USDT.');
      END IF;

      IF length(trim(p_destination_address)) < 8 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid recipient wallet address.');
      END IF;

      -- Network fee calculation
      IF p_network = 'TRC-20' THEN
        v_fee := 1.0;
      ELSIF p_network = 'BEP-20' THEN
        v_fee := 0.8;
      ELSE
        v_fee := 8.0;
      END IF;

      v_net := round(p_amount - v_fee, 2);

      -- Lock wallet
      SELECT * INTO v_wallet FROM public.lottery_wallets 
      WHERE (v_uid IS NOT NULL AND user_id = v_uid) OR (address = p_user_address)
      ORDER BY updated_at DESC LIMIT 1
      FOR UPDATE;

      IF NOT FOUND OR v_wallet.balance < p_amount THEN
        RETURN jsonb_build_object('success', false, 'error', 'Withdrawal amount exceeds available wallet balance.');
      END IF;

      v_new_balance := round(v_wallet.balance - p_amount, 2);
      UPDATE public.lottery_wallets
      SET balance = v_new_balance, updated_at = now()
      WHERE address = v_wallet.address;

      v_now_ms := (EXTRACT(EPOCH FROM now()) * 1000)::bigint;
      v_order_id := 'W-' || floor(random() * 8999 + 1000)::text;

      INSERT INTO public.lottery_withdrawals (
        id,
        user_address,
        amount,
        net_disbursal,
        network_fee,
        network,
        destination_address,
        requested_at,
        sla_target_ms,
        status,
        tx_hash,
        created_at
      ) VALUES (
        v_order_id,
        p_user_address,
        p_amount,
        v_net,
        v_fee,
        p_network,
        trim(p_destination_address),
        v_now_ms,
        v_now_ms + 86400000,
        'processing',
        NULL,
        now()
      );

      RETURN jsonb_build_object(
        'success', true,
        'order_id', v_order_id,
        'new_balance', v_new_balance,
        'net_disbursal', v_net
      );
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.rotate_user_game_seed(p_wallet_address text, p_new_client_seed text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_seed record;
  v_new_server_seed text;
  v_new_server_hash text;
  v_client_seed text;
BEGIN
  SELECT * INTO v_seed FROM public.user_game_seeds WHERE wallet_address = p_wallet_address FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seed pair not found for wallet.');
  END IF;

  v_new_server_seed := 'seed_' || encode(extensions.gen_random_bytes(32), 'hex');
  v_new_server_hash := '0x' || encode(extensions.digest(v_new_server_seed, 'sha256'), 'hex');
  v_client_seed := COALESCE(trim(p_new_client_seed), 'cs_' || substr(md5(random()::text), 1, 12));

  UPDATE public.user_game_seeds
  SET previous_server_seed = active_server_seed,
      previous_server_hash = active_server_hash,
      previous_client_seed = active_client_seed,
      active_server_seed = v_new_server_seed,
      active_server_hash = v_new_server_hash,
      active_client_seed = v_client_seed,
      nonce = 0,
      updated_at = now()
  WHERE wallet_address = p_wallet_address;

  RETURN jsonb_build_object(
    'success', true,
    'revealed_previous_seed', v_seed.active_server_seed,
    'previous_commit_hash', v_seed.active_server_hash,
    'new_server_hash', v_new_server_hash,
    'new_client_seed', v_client_seed,
    'nonce', 0
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_game_round_secure(p_game_id text, p_wallet_address text, p_user_id uuid, p_username text, p_bet_amount numeric, p_multiplier numeric, p_payout numeric, p_outcome_data jsonb, p_server_seed text DEFAULT NULL::text, p_server_seed_hash text DEFAULT NULL::text, p_client_seed text DEFAULT NULL::text, p_nonce integer DEFAULT 1, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_round_id text;
  v_balance_before numeric;
  v_balance_after numeric;
  v_debit_res jsonb;
  v_credit_res jsonb;
  v_status text;
  v_srv_seed text;
  v_srv_hash text;
  v_cli_seed text;
  v_nonce integer;
  v_seed_rec record;
  v_room_id text;
  v_net_profit numeric;
BEGIN
  IF p_bet_amount < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bet amount cannot be negative.');
  END IF;

  v_round_id := 'rnd_' || p_game_id || '_' || to_char(now(), 'YYYYMMDDHH24MISS') || '_' || substr(md5(random()::text), 1, 6);
  v_room_id := COALESCE(p_metadata->>'roomId', p_metadata->>'room_id', 'standard');
  v_net_profit := COALESCE(p_payout, 0) - COALESCE(p_bet_amount, 0);

  -- 1. Resolve Seeds and Nonce
  IF p_server_seed IS NOT NULL AND p_server_seed_hash IS NOT NULL THEN
    v_srv_seed := p_server_seed;
    v_srv_hash := p_server_seed_hash;
    v_cli_seed := COALESCE(p_client_seed, 'cs_default');
    v_nonce := COALESCE(p_nonce, 1);
  ELSE
    -- Fetch or initialize active seed pair for wallet
    SELECT * INTO v_seed_rec FROM public.user_game_seeds WHERE wallet_address = p_wallet_address FOR UPDATE;
    IF NOT FOUND THEN
      v_srv_seed := 'seed_' || encode(extensions.gen_random_bytes(32), 'hex');
      v_srv_hash := '0x' || encode(extensions.digest(v_srv_seed, 'sha256'), 'hex');
      v_cli_seed := COALESCE(p_client_seed, 'cs_' || substr(md5(random()::text), 1, 12));
      v_nonce := 1;

      INSERT INTO public.user_game_seeds (
        wallet_address, user_id, active_server_seed, active_server_hash, active_client_seed, nonce
      ) VALUES (
        p_wallet_address, p_user_id, v_srv_seed, v_srv_hash, v_cli_seed, 1
      );
    ELSE
      v_srv_seed := v_seed_rec.active_server_seed;
      v_srv_hash := v_seed_rec.active_server_hash;
      v_cli_seed := COALESCE(p_client_seed, v_seed_rec.active_client_seed);
      v_nonce := v_seed_rec.nonce + 1;

      UPDATE public.user_game_seeds
      SET nonce = v_nonce, updated_at = now()
      WHERE wallet_address = p_wallet_address;
    END IF;
  END IF;

  -- 2. Debit Stake if > 0
  IF p_bet_amount > 0 THEN
    v_debit_res := public.debit_virtual_credits(
      p_amount => p_bet_amount,
      p_transaction_type => 'game_bet',
      p_reference_id => v_round_id,
      p_description => 'Bet placed on ' || upper(p_game_id) || ' (' || v_room_id || ')',
      p_user_address => p_wallet_address,
      p_metadata => jsonb_build_object('game_id', p_game_id, 'round_id', v_round_id, 'room_id', v_room_id)
    );

    IF NOT (v_debit_res->>'success')::boolean THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', COALESCE(v_debit_res->>'error', 'Insufficient Flow Coin balance.')
      );
    END IF;

    v_balance_after := (v_debit_res->>'new_balance')::numeric;
  ELSE
    SELECT balance INTO v_balance_after FROM public.lottery_wallets WHERE address = p_wallet_address;
    v_balance_after := COALESCE(v_balance_after, 0);
  END IF;

  -- 3. Credit Winnings if > 0
  IF p_payout > 0 THEN
    v_status := 'won';
    v_credit_res := public.credit_virtual_credits(
      p_amount => p_payout,
      p_transaction_type => 'game_win',
      p_reference_id => v_round_id || '_win',
      p_description => 'Payout from ' || upper(p_game_id) || ' (' || p_multiplier || 'x)',
      p_user_address => p_wallet_address,
      p_target_user_id => p_user_id,
      p_metadata => jsonb_build_object('game_id', p_game_id, 'round_id', v_round_id, 'room_id', v_room_id, 'multiplier', p_multiplier)
    );
    IF (v_credit_res->>'success')::boolean THEN
      v_balance_after := (v_credit_res->>'new_balance')::numeric;
    END IF;
  ELSE
    v_status := 'lost';
  END IF;

  -- 4. Record Game Round with room_id (net_profit is generated automatically by postgres)
  INSERT INTO public.game_rounds (
    id,
    game_id,
    room_id,
    user_id,
    wallet_address,
    username,
    bet_amount,
    currency,
    multiplier,
    payout,
    status,
    server_seed,
    server_seed_hash,
    client_seed,
    nonce,
    outcome_data,
    metadata,
    created_at
  ) VALUES (
    v_round_id,
    p_game_id,
    v_room_id,
    p_user_id,
    p_wallet_address,
    p_username,
    p_bet_amount,
    'FC',
    p_multiplier,
    p_payout,
    v_status,
    v_srv_seed,
    v_srv_hash,
    v_cli_seed,
    v_nonce,
    p_outcome_data,
    p_metadata,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'round_id', v_round_id,
    'game_id', p_game_id,
    'room_id', v_room_id,
    'status', v_status,
    'bet_amount', p_bet_amount,
    'multiplier', p_multiplier,
    'payout', p_payout,
    'net_profit', v_net_profit,
    'new_balance', v_balance_after,
    'server_seed_hash', v_srv_hash,
    'server_seed', v_srv_seed,
    'client_seed', v_cli_seed,
    'nonce', v_nonce,
    'outcome_data', p_outcome_data
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.spin_lucky_wheel(p_user_address text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_last_spin timestamptz;
  v_now timestamptz := now();
  v_cooldown integer := 86400; -- 24 hours
  v_elapsed integer;
  v_rand numeric;
  v_slice_index integer;
  v_base_prize numeric;
  v_multiplier numeric := 1.0;
  v_final_prize numeric;
  v_tier text := 'Bronze';
  v_spin_ref text;
  v_credit_res jsonb;
BEGIN
  IF p_user_address IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Wallet address is required');
  END IF;

  -- Check cooldown from user_vip_progress or wallet_ledger
  SELECT last_wheel_spin_at INTO v_last_spin 
  FROM public.user_vip_progress 
  WHERE wallet_address = p_user_address;

  IF v_last_spin IS NULL THEN
    SELECT created_at INTO v_last_spin
    FROM public.wallet_ledger
    WHERE wallet_address = p_user_address AND transaction_type = 'lucky_wheel_spin'
    ORDER BY created_at DESC LIMIT 1;
  END IF;

  IF v_last_spin IS NOT NULL THEN
    v_elapsed := EXTRACT(EPOCH FROM (v_now - v_last_spin))::integer;
    IF v_elapsed < v_cooldown THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Lucky Wheel on 24-hour cooldown. Return in ' || ((v_cooldown - v_elapsed) / 3600) || ' hour(s).',
        'seconds_remaining', (v_cooldown - v_elapsed)
      );
    END IF;
  END IF;

  -- Fetch current VIP multiplier
  SELECT faucet_multiplier, current_tier 
  INTO v_multiplier, v_tier
  FROM public.user_vip_progress 
  WHERE wallet_address = p_user_address;

  IF v_multiplier IS NULL THEN
    v_multiplier := 1.0;
    v_tier := 'Bronze';
  END IF;

  -- Deterministic random prize slice calculation
  -- Slices: [50, 100, 150, 200, 250, 300, 500, 1000]
  v_rand := random() * 100.0;

  IF v_rand < 0.5 THEN
    v_slice_index := 7; v_base_prize := 1000.0; -- 0.5% Jackpot
  ELSIF v_rand < 3.0 THEN
    v_slice_index := 6; v_base_prize := 500.0;  -- 2.5%
  ELSIF v_rand < 8.0 THEN
    v_slice_index := 5; v_base_prize := 300.0;  -- 5.0%
  ELSIF v_rand < 16.0 THEN
    v_slice_index := 4; v_base_prize := 250.0;  -- 8.0%
  ELSIF v_rand < 30.0 THEN
    v_slice_index := 3; v_base_prize := 200.0;  -- 14.0%
  ELSIF v_rand < 50.0 THEN
    v_slice_index := 2; v_base_prize := 150.0;  -- 20.0%
  ELSIF v_rand < 75.0 THEN
    v_slice_index := 1; v_base_prize := 100.0;  -- 25.0%
  ELSE
    v_slice_index := 0; v_base_prize := 50.0;   -- 25.0%
  END IF;

  v_final_prize := ROUND(v_base_prize * v_multiplier, 2);
  v_spin_ref := 'wheel-' || to_char(v_now, 'YYYY-MM-DD') || '-' || substring(p_user_address from 3 for 8);

  -- Credit virtual wallet
  v_credit_res := public.credit_virtual_credits(
    v_final_prize,
    'lucky_wheel_spin',
    v_spin_ref,
    'Daily Lucky Wheel Prize: ' || v_final_prize || ' FC (' || v_tier || ' Tier ' || v_multiplier || 'x)',
    p_user_address,
    v_uid,
    jsonb_build_object('slice', v_slice_index, 'base', v_base_prize, 'vip_mult', v_multiplier)
  );

  -- Upsert last_wheel_spin_at in user_vip_progress
  INSERT INTO public.user_vip_progress (wallet_address, user_id, last_wheel_spin_at, updated_at)
  VALUES (p_user_address, v_uid, v_now, v_now)
  ON CONFLICT (wallet_address) DO UPDATE SET
    last_wheel_spin_at = v_now,
    updated_at = v_now;

  RETURN jsonb_build_object(
    'success', true,
    'slice_index', v_slice_index,
    'base_prize', v_base_prize,
    'vip_multiplier', v_multiplier,
    'final_prize', v_final_prize,
    'vip_tier', v_tier,
    'new_balance', (v_credit_res->>'new_balance')::numeric,
    'message', 'Congratulations! You won ' || v_final_prize || ' Flow Coins!'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_admin_operator_passkey(p_passkey text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_stored_hash text := '6cbfef548840682f637e0036a99a86bd23e4d051e7f2472d2a8f4e07a169d713';
  v_input_hash text;
BEGIN
  IF p_passkey IS NULL OR length(trim(p_passkey)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Operator passkey required');
  END IF;

  v_input_hash := encode(extensions.digest(trim(p_passkey)::bytea, 'sha256'), 'hex');

  IF v_input_hash = v_stored_hash THEN
    RETURN jsonb_build_object('success', true);
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Invalid operator passkey. Access Denied.');
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_lottery_draw_result(p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_event record;
  v_audit record;
  v_computed_commit text;
  v_computed_combined text;
  v_computed_outcome text;
  v_computed_digits text;
  v_is_commit_valid boolean;
  v_is_digits_valid boolean;
BEGIN
  SELECT * INTO v_event FROM public.lottery_events WHERE id = p_event_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('verified', false, 'error', 'Lottery event not found.');
  END IF;

  IF v_event.status <> 'completed' OR v_event.revealed_seed IS NULL THEN
    RETURN jsonb_build_object('verified', false, 'error', 'Draw has not been finalized or revealed yet.');
  END IF;

  SELECT * INTO v_audit FROM public.lottery_draw_audits WHERE event_id = p_event_id LIMIT 1;

  -- Recompute commit hash from revealed seed
  v_computed_commit := '0x' || encode(extensions.digest(v_event.revealed_seed, 'sha256'), 'hex');
  v_is_commit_valid := (v_computed_commit = v_event.sha256_seed);

  -- Recompute outcome digits from revealed seed + client seed
  v_computed_combined := v_event.revealed_seed || ':' || COALESCE(v_event.client_seed, '') || ':' || p_event_id;
  v_computed_outcome := encode(extensions.digest(v_computed_combined, 'sha256'), 'hex');
  v_computed_digits := lpad((('x' || substr(v_computed_outcome, 1, 8))::bit(32)::bigint % 10000)::text, 4, '0');

  v_is_digits_valid := (v_computed_digits = v_event.winning_digits OR (v_audit.winning_digits IS NOT NULL AND v_audit.winning_digits = v_event.winning_digits));

  RETURN jsonb_build_object(
    'verified', (v_is_commit_valid AND v_is_digits_valid),
    'event_id', p_event_id,
    'event_title', v_event.title,
    'published_commit_hash', v_event.sha256_seed,
    'computed_commit_hash', v_computed_commit,
    'commit_hash_match', v_is_commit_valid,
    'revealed_server_seed', v_event.revealed_seed,
    'client_seed', v_event.client_seed,
    'winning_digits', v_event.winning_digits,
    'computed_digits', v_computed_digits,
    'digits_match', v_is_digits_valid,
    'audit_id', v_audit.id,
    'draw_timestamp', v_audit.draw_timestamp
  );
END;
$function$
